<script lang="ts">
  import type { Direction, DirectionViewProps, Precision, Scenario } from '../../contract';
  import { DIRECTIONS, SCENARIOS } from '../../contract';
  import MapSurface from '../../components/MapSurface.svelte';
  import RecordList from '../../components/RecordList.svelte';

  let { state, records, dispatch }: DirectionViewProps = $props();
  const categories = ['Poultry', 'Pig', 'Dairy', 'Processing', 'Laboratory', 'Aquaculture'];
  const precisions: readonly Precision[] = ['exact', 'city', 'coarse', 'unmapped'];
  const selectedRecord = $derived(records.find(record => record.id === state.selectedId) ?? null);
  const mappedRecords = $derived(records.filter(record => record.latitude !== null && record.longitude !== null));
  const activeFilterCount = $derived(state.filters.categories.length + state.filters.precisions.length);

  function toggleCategory(category: string, checked: boolean) {
    const categories = checked ? [...state.filters.categories, category] : state.filters.categories.filter(item => item !== category);
    dispatch({ type: 'filters', value: { ...state.filters, categories } });
  }
  function togglePrecision(precision: Precision, checked: boolean) {
    const values = checked ? [...state.filters.precisions, precision] : state.filters.precisions.filter(item => item !== precision);
    dispatch({ type: 'filters', value: { ...state.filters, precisions: values } });
  }
</script>

<section class="field-view" data-scenario={state.scenario} aria-label="Field map design direction">
  <header class="spine">
    <a class="brand" href="#/map?f1a=field" aria-label="Until Every Cage map home"><span class="brand-mark" aria-hidden="true">UEC</span><span>Until Every Cage</span></a>
    <nav aria-label="Main navigation"><a href="#/map?f1a=field" aria-current="page">Map</a><a href="#/database">Database</a></nav>
    <form class="search" role="search" onsubmit={event => event.preventDefault()}>
      <label for="field-search">Search all synthetic records</label><span aria-hidden="true">⌕</span>
      <input id="field-search" type="search" placeholder="Name, category, country, or place" value={state.query} oninput={event => dispatch({ type: 'query', value: event.currentTarget.value })} /><kbd aria-hidden="true">/</kbd>
    </form>
    <details class="filters">
      <summary><span aria-hidden="true">≡</span> Filters {#if activeFilterCount}<b>{activeFilterCount}</b>{/if}</summary>
      <div class="filter-sheet">
        <header><strong>Refine records</strong><small>{activeFilterCount} active</small></header>
        <p class="filter-help">OR within each group · groups narrow together</p>
        <fieldset><legend>Category</legend>{#each categories as category}<label><input type="checkbox" checked={state.filters.categories.includes(category)} onchange={event => toggleCategory(category, event.currentTarget.checked)} />{category}</label>{/each}</fieldset>
        <fieldset><legend>Location precision</legend>{#each precisions as precision}<label><input type="checkbox" checked={state.filters.precisions.includes(precision)} onchange={event => togglePrecision(precision, event.currentTarget.checked)} />{precision === 'exact' ? 'Exact site' : precision === 'city' ? 'City-level' : precision === 'coarse' ? 'Coarse area' : 'Unmapped'}</label>{/each}</fieldset>
        <button type="button" onclick={() => dispatch({ type: 'reset-filters' })}>Reset search and filters</button>
      </div>
    </details>
    <div class="review-tools" aria-label="Development review controls">
      <label>Direction<select aria-label="Direction" value={state.direction} onchange={event => dispatch({ type: 'direction', value: event.currentTarget.value as Direction })}>{#each DIRECTIONS as direction}<option value={direction}>{direction}</option>{/each}</select></label>
      <label>Scenario<select aria-label="Scenario" value={state.scenario} onchange={event => dispatch({ type: 'scenario', value: event.currentTarget.value as Scenario })}>{#each SCENARIOS as scenario}<option value={scenario}>{scenario}</option>{/each}</select></label>
    </div>
    <span class="data-mark"><i aria-hidden="true"></i>Synthetic · development only</span>
  </header>

  <section class:results-closed={!state.listOpen} class="map-stage" aria-label="Investigative map field">
    <h1 class="sr-only">Investigative map</h1>
    {#if state.scenario === 'loading'}
      <div class="status" role="status"><i></i><strong>Loading synthetic records</strong><span>Building the field view…</span></div>
    {:else if state.scenario === 'error'}
      <div class="status error" role="alert"><i></i><strong>Records unavailable</strong><span>The test failure is contained. No live fallback was attempted.</span></div>
    {:else}
      <MapSurface records={mappedRecords} {state} onselect={id => dispatch({ type: 'select', value: id })} oncluster={value => dispatch({ type: 'cluster', value })} onbasemap={value => dispatch({ type: 'basemap', value })} onviewport={value => dispatch({ type: 'viewport', value })} />
    {/if}
    {#if state.scenario === 'empty' || (state.scenario !== 'loading' && state.scenario !== 'error' && records.length === 0)}
      <div class="empty" role="status"><small>NO ELIGIBLE RECORDS</small><p>No synthetic records match these search and filter settings.</p><button type="button" onclick={() => dispatch({ type: 'reset-filters' })}>Clear search and filters</button></div>
    {/if}
    {#if selectedRecord && state.scenario !== 'loading' && state.scenario !== 'error'}
      <aside class="reading-sheet" aria-labelledby="record-title" aria-live="polite">
        <div class="sheet-grip" aria-hidden="true"></div>
        <div class="sheet-meta"><span>Selected record</span><span>{selectedRecord.id}</span></div>
        <button class="close" type="button" aria-label="Close record preview" onclick={() => dispatch({ type: 'select', value: null })}>×</button>
        <p class="category">{selectedRecord.category}<i> / </i>{selectedRecord.precision} location</p>
        <h2 id="record-title">{selectedRecord.name}</h2>
        <p class="place"><span aria-hidden="true">⌖</span> {selectedRecord.locality}, {selectedRecord.country}</p>
        <div class="rule"></div><p class="note">Synthetic record for interface review. It makes no factual claim.</p>
      </aside>
    {/if}
  </section>

  <section class:closed={!state.listOpen} class="results" aria-label="Synchronized results">
    <div class="results-bar">
      <button class="results-toggle" type="button" aria-expanded={state.listOpen} aria-controls="field-record-list" onclick={() => dispatch({ type: 'list', value: !state.listOpen })}>
        <span aria-hidden="true">{state.listOpen ? '⌄' : '⌃'}</span>{state.listOpen ? 'Results' : 'Browse results'}<b>{records.length}</b>
      </button>
      <p><i aria-hidden="true"></i>{mappedRecords.length} mapped <span>·</span> {records.filter(record => record.precision === 'unmapped').length} without coordinates</p>
      <small>Select a mark or record to inspect</small>
      <em><i aria-hidden="true"></i>List ↔ map</em>
    </div>
    <div id="field-record-list" class="results-content" hidden={!state.listOpen || state.scenario === 'loading' || state.scenario === 'error'}>
      <RecordList records={records} selectedId={state.selectedId} onselect={id => dispatch({ type: 'select', value: id })} />
    </div>
  </section>
</section>

