list ol){display:block}.results-content :global(.record-list li){min-width:0;border-right:0;border-bottom:1px solid #333b37}.results-content :global(.record-list button){min-height:4.6rem;padding:.7rem .9rem}.reading-sheet{right:.65rem;bottom:calc(min(44vh,23rem) + .65rem);width:min(24rem,calc(100% - 1.3rem));padding:1rem 1.1rem}.map-stage.results-closed .reading-sheet{bottom:3.8rem}}
